return ['domain'=>'wp-certificates','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_ES','project-id-version'=>'WP Certificates 1.0.29','pot-creation-date'=>'2026-10-03T14:28:26+00:00','po-revision-date'=>'2026-10-02 23:50+0000','messages'=>['WP Certificates'=>'WP Certificates','The WordPress plugin for certificates, certificates and personalized documents of the institution.'=>'El plugin de WordPress para los certificados y documentos personalizados de la institución.','EduSof'=>'Edusof','https://edusof.com'=>'https://edusof.com','API connections'=>'Conexiones API','Sorry, you are not allowed to access this page.'=>'Lo sentimos, no tiene permiso para acceder a esta página.','The key was revoked: it no longer works.'=>'La clave se revocó: ya no funciona.','The key does not exist or was already revoked.'=>'La clave no existe o ya estaba revocada.','Card adjusted successfully.'=>'Carnet ajustado correctamente.','Certification deleted successfully.'=>'Certificado eliminado correctamente.','View Details'=>'Ver detalles','Certificate'=>'Certificado','User'=>'Usuario','Actions'=>'Acciones','Certification adjusted successfully.'=>'Certificado ajustado correctamente.','Template adjusted successfully.'=>'Plantilla ajustada correctamente.','Template deleted successfully.'=>'Plantilla eliminada correctamente.','This document requires signatures: it cannot be issued here. Configure its signers and issue it for signature from the student file; each responsible person signs from their own account.'=>'Este documento exige firmas: no se puede emitir aquí. Configure sus firmantes y emítalo para firma desde la ficha del estudiante; cada responsable firma desde su propia cuenta.','An error occurred while trying to issue the certificate'=>'Ocurrió un error al intentar emitir el certificado','There have been problems issuing certificates to the following students:'=>'Hubo problemas al emitir los certificados de los siguientes estudiantes:','The certificates have been success